// Pure dashboard logic: no DOM, no fetch. Tested with `node --test dashboard/tests/`.

export const DEFAULT_STATUS = "pending";

const ESCAPES = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };

export function escapeHtml(value) {
  return String(value ?? "").replace(/[&<>"']/g, (ch) => ESCAPES[ch]);
}

// Local date as YYYY-MM-DD, the same shape shipctl stores in `due`.
export function todayString(now = new Date()) {
  const pad = (n) => String(n).padStart(2, "0");
  return `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
}

// Overdue = pending with a due date strictly before today (same rule as `shipctl stats`).
export function isOverdue(task, today) {
  return task.status === "pending" && Boolean(task.due) && task.due < today;
}

export function ownersOf(tasks) {
  return [...new Set(tasks.map((t) => t.owner).filter(Boolean))].sort();
}

// owner: "" means any owner. status: "all" means any status. Both must match (AND).
export function filterTasks(tasks, { owner = "", status = DEFAULT_STATUS } = {}) {
  return tasks
    .filter((t) => (owner === "" || t.owner === owner) && (status === "all" || t.status === status))
    .sort((a, b) => (a.due || "9999-12-31").localeCompare(b.due || "9999-12-31") || a.id - b.id);
}

export function computeKpis(tasks, notes, today) {
  return {
    open: tasks.filter((t) => t.status === "pending").length,
    completed: tasks.filter((t) => t.status === "done").length,
    overdue: tasks.filter((t) => isOverdue(t, today)).length,
    notes: notes.length,
  };
}

export function allTags(notes) {
  return [...new Set(notes.flatMap((n) => n.tags || []))].sort();
}

// Case-insensitive match on title + body; tag "" means no tag filter.
export function filterNotes(notes, { q = "", tag = "" } = {}) {
  const needle = q.trim().toLowerCase();
  return notes.filter(
    (n) =>
      (tag === "" || (n.tags || []).includes(tag)) &&
      (needle === "" || `${n.title}\n${n.body}`.toLowerCase().includes(needle)),
  );
}

// Clicking the active tag clears it; clicking any other tag selects it.
export function toggleTag(current, tag) {
  return current === tag ? "" : tag;
}

export function firstLine(text) {
  return String(text ?? "").split("\n")[0];
}

