import {
  DEFAULT_STATUS,
  allTags,
  computeKpis,
  escapeHtml as esc,
  filterNotes,
  filterTasks,
  firstLine,
  isOverdue,
  ownersOf,
  todayString,
  toggleTag,
} from "./logic.mjs";

// The wireframe shows a target-date badge but no API provides one. Set a YYYY-MM-DD string to show it.
const TARGET_DATE = null;

const $ = (id) => document.getElementById(id);
const state = { tasks: [], notes: [], owner: "", status: DEFAULT_STATUS, q: "", tag: "" };
const today = todayString();

async function getJson(path) {
  const res = await fetch(path);
  if (!res.ok) throw new Error(`${path} returned ${res.status}`);
  return res.json();
}

function renderKpis() {
  const k = computeKpis(state.tasks, state.notes, today);
  $("kpi-open").textContent = k.open;
  $("kpi-completed").textContent = k.completed;
  $("kpi-overdue").textContent = k.overdue;
  $("kpi-notes").textContent = k.notes;
}

function renderOwnerOptions() {
  const options = ['<option value="">Owner: all</option>']
    .concat(ownersOf(state.tasks).map((o) => `<option value="${esc(o)}">${esc(o)}</option>`));
  $("owner-filter").innerHTML = options.join("");
  $("owner-filter").value = state.owner;
}

function renderTasks() {
  const rows = filterTasks(state.tasks, state);
  $("tasks-empty").hidden = rows.length > 0;
  $("tasks-table").hidden = rows.length === 0;
  $("tasks-body").innerHTML = rows
    .map((t) => {
      const overdue = isOverdue(t, today);
      return `<tr>
        <td data-label="Task">${esc(t.title)}</td>
        <td data-label="Owner">${esc(t.owner || "-")}</td>
        <td data-label="Due" class="${overdue ? "overdue" : ""}">${esc(t.due || "-")}</td>
        <td data-label="Status"><span class="pill pill-${esc(t.status)}">${esc(t.status)}</span></td>
      </tr>`;
    })
    .join("");
}

function renderTags() {
  $("tag-chips").innerHTML = allTags(state.notes)
    .map((tag) => {
      const active = tag === state.tag;
      return `<button type="button" class="chip${active ? " active" : ""}" data-tag="${esc(tag)}" aria-pressed="${active}">#${esc(tag)}</button>`;
    })
    .join("");
}

function renderNotes() {
  const notes = filterNotes(state.notes, state);
  $("notes-empty").hidden = notes.length > 0;
  $("notes-list").innerHTML = notes
    .map(
      (n) => `<li class="note">
        <h3>${esc(n.title)}</h3>
        <p>${esc(firstLine(n.body))}</p>
        <p class="tags">${(n.tags || []).map((t) => `#${esc(t)}`).join(" ")}</p>
      </li>`,
    )
    .join("");
}

function wire() {
  $("owner-filter").addEventListener("change", (e) => {
    state.owner = e.target.value;
    renderTasks();
  });
  $("status-filter").addEventListener("change", (e) => {
    state.status = e.target.value;
    renderTasks();
  });
  $("note-search").addEventListener("input", (e) => {
    state.q = e.target.value;
    renderNotes();
  });
  $("tag-chips").addEventListener("click", (e) => {
    const chip = e.target.closest("button[data-tag]");
    if (!chip) return;
    state.tag = toggleTag(state.tag, chip.dataset.tag);
    renderTags();
    renderNotes();
  });
}

async function main() {
  $("target-date").textContent = TARGET_DATE ? `Target date: ${TARGET_DATE}` : "Target date: not set";
  $("status-filter").value = state.status;
  wire();
  try {
    [state.tasks, state.notes] = await Promise.all([getJson("/api/tasks"), getJson("/api/notes")]);
  } catch (err) {
    $("load-error").textContent = `Could not load data: ${err.message}`;
    $("load-error").hidden = false;
    return;
  }
  renderKpis();
  renderOwnerOptions();
  renderTasks();
  renderTags();
  renderNotes();
}

main();

