:root {
  --ink: #2b2b2b;
  --muted: #666;
  --paper: #fbfaf7;
  --line: #2b2b2b;
  --red: #c0392b;
  --gap: 16px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font: 16px/1.4 system-ui, sans-serif;
}

main { max-width: 1100px; margin: 0 auto; padding: var(--gap); display: grid; gap: var(--gap); }

h1, h2, h3, p { margin: 0; }
h1 { font-size: 1.6rem; }
h2 { font-size: 1.3rem; }
h3 { font-size: 1.05rem; font-weight: 600; }

.panel, .card, .note { border: 2px solid var(--line); border-radius: 8px; background: #fff; }
.panel { padding: var(--gap); }

.header { display: flex; justify-content: space-between; align-items: center; gap: var(--gap); }
.eyebrow { font-size: .85rem; text-transform: uppercase; letter-spacing: .05em; }

.badge, .pill, .chip {
  border: 2px solid var(--line);
  border-radius: 999px;
  padding: 2px 14px;
  background: #fff;
  color: var(--ink);
  font: inherit;
  font-size: .9rem;
  white-space: nowrap;
}

.kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--gap); }
.card { padding: var(--gap); display: grid; gap: 8px; }
.label { font-size: .85rem; text-transform: uppercase; }
.card strong { font-size: 1.8rem; }

.overdue { color: var(--red); }

.panel-head { display: flex; justify-content: space-between; align-items: center; gap: var(--gap); margin-bottom: var(--gap); }
.filters { display: flex; gap: 12px; }

select, input[type="search"] {
  font: inherit;
  padding: 6px 10px;
  border: 2px solid var(--line);
  border-radius: 8px;
  background: #fff;
  color: var(--ink);
}
input[type="search"] { min-width: 260px; }

table { width: 100%; border-collapse: collapse; }
th { text-align: left; font-size: .85rem; text-transform: uppercase; border-bottom: 2px solid var(--line); padding: 8px; }
td { padding: 8px; }
th:first-child, td:first-child { width: 45%; }

.chips { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: var(--gap); }
.chip { cursor: pointer; }
.chip.active { background: var(--ink); color: #fff; }

.notes { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; }
.note { padding: 10px 14px; }
.note p { color: var(--muted); font-size: .9rem; }
.note .tags { margin-top: 2px; }

.empty { color: var(--muted); padding: 12px 8px; }
.error { border: 2px solid var(--red); color: var(--red); border-radius: 8px; padding: 10px 14px; background: #fff; }

[hidden] { display: none !important; }

@media (max-width: 759px) {
  .kpis { grid-template-columns: repeat(2, 1fr); }
  .header, .panel-head { flex-direction: column; align-items: stretch; }
  .filters { flex-direction: column; }
  input[type="search"] { min-width: 0; width: 100%; }

  table, tbody, tr, td { display: block; width: 100%; }
  thead { display: none; }
  tr { border: 2px solid var(--line); border-radius: 8px; padding: 8px; margin-bottom: 12px; }
  td, th:first-child, td:first-child { width: 100%; padding: 4px 8px; }
  td::before { content: attr(data-label) ": "; font-size: .8rem; text-transform: uppercase; color: var(--muted); }
}

