import { test } from "node:test";
import assert from "node:assert/strict";

import {
  allTags,
  computeKpis,
  escapeHtml,
  filterNotes,
  filterTasks,
  isOverdue,
  ownersOf,
  todayString,
  toggleTag,
} from "../js/logic.mjs";

const TODAY = "2026-10-10";
const tasks = [
  { id: 1, title: "Cut branch", owner: "ana", due: "2026-10-01", status: "pending" },
  { id: 2, title: "Write notes", owner: "ben", due: "2026-10-20", status: "pending" },
  { id: 3, title: "Tag build", owner: "ana", due: "2026-09-01", status: "done" },
  { id: 4, title: "Smoke test", owner: "ana", due: null, status: "pending" },
  { id: 5, title: "Due today", owner: "ben", due: TODAY, status: "pending" },
];
const notes = [
  { id: 1, title: "Deploy plan", body: "Roll out on Tuesday\nsecond line", tags: ["ops", "release:v1.4"] },
  { id: 2, title: "Flaky test", body: "backend retries", tags: ["qa", "backend"] },
  { id: 3, title: "Untagged", body: "nothing", tags: [] },
];

test("overdue requires pending status and a due date before today", () => {
  assert.equal(isOverdue(tasks[0], TODAY), true);
  assert.equal(isOverdue(tasks[1], TODAY), false);
  assert.equal(isOverdue(tasks[2], TODAY), false, "done tasks are never overdue");
  assert.equal(isOverdue(tasks[3], TODAY), false, "no due date is not overdue");
  assert.equal(isOverdue(tasks[4], TODAY), false, "due today is not overdue");
});

test("task filter defaults to pending", () => {
  assert.deepEqual(filterTasks(tasks).map((t) => t.id), [1, 5, 2, 4]);
});

test("owner and status filters combine with AND", () => {
  assert.deepEqual(filterTasks(tasks, { owner: "ana", status: "pending" }).map((t) => t.id), [1, 4]);
  assert.deepEqual(filterTasks(tasks, { owner: "ana", status: "done" }).map((t) => t.id), [3]);
  assert.deepEqual(filterTasks(tasks, { owner: "ben", status: "done" }), []);
});

test("status all returns every status", () => {
  assert.equal(filterTasks(tasks, { status: "all" }).length, 5);
});

test("filtering does not reorder the input array", () => {
  const copy = tasks.map((t) => t.id);
  filterTasks(tasks, { status: "all" });
  assert.deepEqual(tasks.map((t) => t.id), copy);
});

test("kpis count open, completed, overdue and notes", () => {
  assert.deepEqual(computeKpis(tasks, notes, TODAY), { open: 4, completed: 1, overdue: 1, notes: 3 });
});

test("owners are unique and sorted", () => {
  assert.deepEqual(ownersOf(tasks), ["ana", "ben"]);
});

test("tags are unique and sorted", () => {
  assert.deepEqual(allTags(notes), ["backend", "ops", "qa", "release:v1.4"]);
});

test("note search matches title and body case-insensitively", () => {
  assert.deepEqual(filterNotes(notes, { q: "DEPLOY" }).map((n) => n.id), [1]);
  assert.deepEqual(filterNotes(notes, { q: "retries" }).map((n) => n.id), [2]);
  assert.deepEqual(filterNotes(notes, { q: "zzz" }), []);
});

test("search and tag filters combine with AND", () => {
  assert.deepEqual(filterNotes(notes, { q: "test", tag: "qa" }).map((n) => n.id), [2]);
  assert.deepEqual(filterNotes(notes, { q: "deploy", tag: "qa" }), []);
});

test("clicking a tag selects it and clicking it again clears it", () => {
  assert.equal(toggleTag("", "ops"), "ops");
  assert.equal(toggleTag("ops", "ops"), "");
  assert.equal(toggleTag("ops", "qa"), "qa");
});

test("escapeHtml neutralises markup from API values", () => {
  assert.equal(escapeHtml(`<img src=x onerror="a('b')">&`), "&lt;img src=x onerror=&quot;a(&#39;b&#39;)&quot;&gt;&amp;");
  assert.equal(escapeHtml(null), "");
});

test("todayString formats local date as YYYY-MM-DD", () => {
  assert.equal(todayString(new Date(2026, 0, 5)), "2026-01-05");
});

